res.format = function(obj) {
  var req = this.req;
  var type = req.headers['accept'];

  // If no type is specified, default to 'text/plain'
  if (!type) {
    type = 'text/plain';
  }

  // If the object is a string, return it directly
  if (typeof obj === 'string') {
    return this.send(obj);
  }

  // If the object is an object, determine the best content type
  if (typeof obj === 'object') {
    for (var key in obj) {
      if (type.indexOf(key) !== -1) {
        return this.send(obj[key]);
      }
    }
  }

  // If no matching content type is found, default to 'text/plain'
  return this.send(JSON.stringify(obj));
};

