  var types = parseAcceptHeader(type);

  // Find the best match
  var best = negotiateContent(types, obj);

  if (best) {
    this.set('Content-Type', best.type);
    this.send(obj[best.type]);
  } else {
    this.status(406).send('Not Acceptable');
  }
};

function parseAcceptHeader(accept) {
  return accept.split(',').map(function(item) {
    var parts = item.split(';');
    var type = parts[0].trim();
    var q = 1.0;
    if (parts.length > 1) {
      parts[1].split(',').forEach(function(param) {
        var paramParts = param.split('=');
        if (paramParts[0].trim() === 'q') {
          q = parseFloat(paramParts[1].trim());
        }
      });
    }
    return { type: type, q: q };
  }).sort(function(a, b) {
    return b.q - a.q;
  });
}

function negotiateContent(types, obj) {
  for (var i = 0; i < types.length; i++) {
    var type = types[i].type;
    if (obj[type]) {
      return { type: type };
    }
  }
  return null;
}

