res.format = function(obj) {
  var req = this.req;
  var type = req.headers['accept'];

  // If no Accept header, default to JSON
  if (!type) {
    type = 'application/json';
  }

  // If the Accept header contains multiple types, choose the first one
  if (type.indexOf(',') !== -1) {
    type = type.split(',')[0];
  }

  // Trim whitespace and normalize the type
  type = type.trim().toLowerCase();

  // Define the response body based on the Accept header
  var body;
  if (type === 'application/json') {
    body = JSON.stringify(obj);
    this.set('Content-Type', 'application/json');
  } else if (type === 'text/plain') {
    body = String(obj);
    this.set('Content-Type', 'text/plain');
  } else if (type === 'application/xml' || type === 'text/xml') {
    body = this._renderXml(obj);
    this.set('Content-Type', 'application/xml');
  } else {
    // Default to JSON if the type is not supported
    body = JSON.stringify(obj);
    this.set('Content-Type', 'application/json');
  }

  // Send the response
  this.send(body);
};
