```javascript
res.format = function(obj) {
  var req = this.req;
  var types = Object.keys(obj);

  // get all types that this request accepts
  var acceptedTypes = accept(req.headers.accept);

  // get the best match
  var matchedType = acceptedTypes.type(types);

  // if we have a match, send the response
  if (matchedType) {
    this.set('Content-Type', matchedType);
    obj[matchedType](req, this);
  } else {
    // if no match, respond with 406 Not Acceptable
    this.status(406).send('Not Acceptable');
  }
};
```
